// Mirrors postgrest-js's GenericTable shape (Row/Insert/Update/Relationships)
// so supabase-js's type inference for insert/update/select resolves
// correctly instead of collapsing to `never`. Relationships is left empty
// (no embedded-resource typing) — this codebase deliberately avoids
// PostgREST embedded selects in favour of separate queries, so no
// relationship metadata is needed. See the file header note on
// regenerating this file from a live project.
type TableDef<Row, Insert, Update = Partial<Insert>> = {
  Row: Row;
  Insert: Insert;
  Update: Update;
  Relationships: [];
};

export type Database = {
  public: {
    Tables: {
      profiles: TableDef<Profile, Partial<Profile> & { id: string }>;
      clients: TableDef<
        Client,
        Partial<Omit<Client, 'id' | 'organisation_id' | 'created_at' | 'updated_at'>> & {
          name: string;
        }
      >;
      notes: TableDef<
        Note,
        Partial<Omit<Note, 'id' | 'organisation_id' | 'created_at' | 'updated_at'>> & {
          client_id: string;
          author_id: string;
          text: string;
        }
      >;
      shifts: TableDef<
        Shift,
        Partial<Omit<Shift, 'id' | 'organisation_id' | 'created_at' | 'updated_at'>> & {
          client_id: string;
          staff_id: string;
          date: string;
        }
      >;
      tasks: TableDef<
        Task,
        Partial<Omit<Task, 'id' | 'organisation_id' | 'created_at' | 'updated_at'>> & {
          title: string;
        }
      >;
      share_tokens: TableDef<
        ShareTokenRow,
        Partial<Omit<ShareTokenRow, 'id' | 'organisation_id' | 'created_at' | 'token'>> & {
          client_id: string;
        }
      >;
      task_tags: TableDef<
        TaskTag,
        Partial<Omit<TaskTag, 'id' | 'organisation_id' | 'created_at'>> & { task_id: string }
      >;
      documents: TableDef<
        DocumentRow,
        Partial<Omit<DocumentRow, 'id' | 'organisation_id' | 'created_at' | 'updated_at'>> & {
          title: string;
          category: DocumentCategory;
          uploader_id: string;
        }
      >;
      transactions: TableDef<
        Transaction,
        Partial<Omit<Transaction, 'id' | 'organisation_id' | 'created_at' | 'updated_at'>> & {
          type: TransactionType;
          category: string;
          amount: number;
        }
      >;
      onboarding_records: TableDef<
        OnboardingRecord,
        Partial<Omit<OnboardingRecord, 'id' | 'organisation_id' | 'created_at' | 'updated_at'>> & {
          person_id: string;
          step: OnboardingStep;
        }
      >;
      reportable_incidents: TableDef<
        ReportableIncident,
        Partial<
          Omit<ReportableIncident, 'id' | 'organisation_id' | 'created_at' | 'updated_at'>
        > & {
          category: IncidentCategory;
          reported_by: string;
          incident_at: string;
          description: string;
        }
      >;
      risk_register: TableDef<
        RiskRegisterEntry,
        Partial<Omit<RiskRegisterEntry, 'id' | 'organisation_id' | 'created_at' | 'updated_at'>> & {
          title: string;
          category: RiskCategory;
          likelihood: RiskLevel;
          impact: RiskLevel;
        }
      >;
    };
    Views: Record<string, never>;
    Functions: {
      get_coordinated_summary: {
        Args: { p_token: string };
        Returns: {
          name: string;
          routines: string | null;
          communication_preferences?: string | null;
          goals?: string | null;
          care_plan?: string | null;
        } | null;
      };
    };
  };
};
